// Generated By AI Start (Cursor)
/**
 * 与 Cursor「共享大脑」扩展共用 sync-coordinator / sync-registry，避免双写打架。
 * Cursor 写 ~/.cursor/rules/shared-brain/；DSH 写 memory.json；由 generation 协调。
 */
import { createHash } from 'node:crypto'
import { existsSync, mkdirSync, readFileSync, readdirSync, renameSync, rmSync, statSync, watch, writeFileSync } from 'node:fs'
import { homedir } from 'node:os'
import { join } from 'node:path'
import { readStore, writeStore, newId, mirrorBottomlineEntries } from './store.js'
import { writeFileAtomicSync } from './atomic-write.js'
import { readModules, writeModules } from './modules.js'
import { redactSecrets } from './summarize.js'
import { sanitizeForPrompt } from './weighted-recall.js'

/**
 * 外部来源（Cursor 规则文件、别人写的规则）进来的正文，统一过一遍：
 * 先脱敏，再中和提示词标签。
 *
 * 2026-11-12 加：以前只脱敏，不处理注入话术 —— 而 Cursor 的规则文件是另一个工具写的，
 * 内容完全不受我们控制。它会进记忆库、再进系统提示词，等于开了一条绕过黑名单的路。
 * 用 sanitizeForPrompt 的非 strict 模式（只屏蔽命中注入话术的那一句，不整条丢弃），
 * 免得把好好的规则整条干掉。
 */
function externalTextIn(text) {
  return sanitizeForPrompt(redactSecrets(String(text ?? '')))
}

// 2026-11-11：允许用环境变量指到别处，测试才能在临时目录里伪造规则，
// 不用碰真实的 ~/.cursor。生产环境不设这两个变量，行为完全不变。
const CURSOR_BRAIN = process.env.DSH_SHARED_BRAIN_CURSOR_BRAIN
  ? process.env.DSH_SHARED_BRAIN_CURSOR_BRAIN
  : join(homedir(), '.cursor', 'storages', 'cursor-shared-brain')
const COORD_FILE = join(CURSOR_BRAIN, 'sync-coordinator.json')
// 2026-11-11：记「上次从 Cursor 收到的是什么内容」（按条目 id + 内容指纹）。
// 没这个的话，Cursor 侧只是碰了下文件、时间戳变了，也会被当成新内容重新写一遍，
// 把 DSH 里的 updatedAt 推新、让老记忆装成刚更新；更糟的是本机刚改过的正文会被盖回去。
const SYNC_STATE_FILE = join(CURSOR_BRAIN, 'cursor-sync-state.json')
/** Cursor 侧时钟最多允许比本机快这么多；再快就当写错了，按本机时间算。 */
const CLOCK_SKEW_MS = 60 * 1000

function hashText(text) {
  return createHash('sha1').update(String(text ?? ''), 'utf8').digest('hex').slice(0, 16)
}

function readSyncState() {
  if (!existsSync(SYNC_STATE_FILE)) return { version: 1, rules: {} }
  try {
    const raw = JSON.parse(readFileSync(SYNC_STATE_FILE, 'utf8'))
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return { version: 1, rules: {} }
    // 兼容旧形态：以前是 { [entryId]: { hash, at } }，没有 rules 这层
    if (!raw.rules || typeof raw.rules !== 'object') return { version: 1, rules: {} }
    return { version: 1, rules: raw.rules }
  } catch {
    // 坏了就当没记过：最多多导一次，比抛出去强
    return { version: 1, rules: {} }
  }
}

function writeSyncState(state) {
  mkdirSync(CURSOR_BRAIN, { recursive: true })
  // 2026-11-11：同 writeCoord，走带重试与兜底的原子写（Windows 上 rename 会被占用挡下）。
  writeFileAtomicSync(SYNC_STATE_FILE, `${JSON.stringify(state, null, 2)}\n`)
}
const REGISTRY_FILE = join(CURSOR_BRAIN, 'sync-registry.json')
const CURSOR_RULES = process.env.DSH_SHARED_BRAIN_CURSOR_RULES
  ? process.env.DSH_SHARED_BRAIN_CURSOR_RULES
  : join(homedir(), '.cursor', 'rules', 'shared-brain')

function defaultCoord() {
  return {
    version: 1,
    generation: 0,
    writer: null,
    writerAt: 0,
    cursorApplied: 0,
    dshApplied: 0,
    suppressWatchUntil: 0,
  }
}

export function readCoord() {
  if (!existsSync(COORD_FILE)) return defaultCoord()
  try {
    return { ...defaultCoord(), ...JSON.parse(readFileSync(COORD_FILE, 'utf8')) }
  } catch {
    return defaultCoord()
  }
}

function writeCoord(c) {
  mkdirSync(CURSOR_BRAIN, { recursive: true })
  // 2026-11-11：改成「写临时文件再 rename」。原来是直接覆盖写，
  // 进程半路被杀就留下半截 JSON —— readCoord 会静默回默认值，
  // generation 归零，下一轮 Cursor 侧改动会被当成「全新的」再导一遍。
  // 同一天补：Windows 上 rename 到被别的进程开着的目标会抛 EPERM
  // （真插件正开着这个协调文件），所以统一走带重试和兜底的原子写。
  writeFileAtomicSync(COORD_FILE, `${JSON.stringify(c, null, 2)}\n`, {
    onFallback: (error) => {
      console.warn(`[dsh-shared-brain] 协调文件改不成原子写（${error?.code ?? error?.message}），已退回直接覆盖`)
    },
  })
}

export function beginWriteDsh() {
  const c = readCoord()
  const now = Date.now()
  if (c.writer && c.writer !== 'dsh' && now - c.writerAt < 8000) {
    return { ok: false }
  }
  c.writer = 'dsh'
  c.writerAt = now
  writeCoord(c)
  // 2026-11-11：把「我开工时看到的是第几代」带回去。写盘期间别人可能又推进了一代，
  // 结束时若直接 dshApplied = generation，就把没导入过的改动标成「已应用」了。
  return { ok: true, generation: c.generation }
}

export function finishWriteDsh(options = {}) {
  const bump = options.bump !== false
  const c = readCoord()
  const base = Number.isFinite(Number(options.baseGeneration)) ? Number(options.baseGeneration) : c.generation
  const expected = base + (bump ? 1 : 0)
  if (bump) c.generation += 1
  c.writer = null
  c.writerAt = 0
  // 只有「这一代里没有别人插进来」才认作全都应用过了；否则记到开工那一代，
  // 让下一轮把别人推进的那一代导进来。0.9 那条「coord 被伪造/并发就丢改动」修的就是这里。
  c.dshApplied = c.generation === expected ? c.generation : Math.max(c.dshApplied, base)
  c.suppressWatchUntil = Date.now() + (options.suppressMs ?? 2500)
  writeCoord(c)
}

export function shouldDshReact() {
  const c = readCoord()
  const now = Date.now()
  if (now < c.suppressWatchUntil) return false
  return c.generation > c.dshApplied || c.writer === 'cursor'
}

function parseFrontmatter(raw) {
  const m = String(raw).match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?/)
  if (!m) return { front: {}, body: String(raw).trim() }
  const front = {}
  for (const line of m[1].split(/\r?\n/)) {
    const idx = line.indexOf(':')
    if (idx < 0) continue
    const key = line.slice(0, idx).trim()
    let val = line.slice(idx + 1).trim()
    if (val === 'true') val = true
    if (val === 'false') val = false
    else if (/^\d+$/.test(val)) val = Number(val)
    front[key] = val
  }
  return { front, body: String(raw).slice(m[0].length).trim() }
}

// 2026-11-02 改：
// 原来只扫 memory/ 一个目录 —— Cursor 侧的 cognition/、emotion/、instinct/ 都没被扫到，
// 等于只同步了一半的记忆；而 bottomline/ 目录里的东西又跟 DSH 的底线模块打架。
// 现在：
//   1) 扫全部「记忆类」子目录，frontmatter 里的 module 字段说了算；
//   2) bottomline / user 一律跳过 —— 底线只认手动注入，Cursor 同步不碰它。
//      （Cursor 扩展那边原本把 bottomline/*.mdc 当权威源，会把 DSH 删掉的底线灌回来）
const CURSOR_MEMORY_SUBDIRS = ['memory', 'cognition', 'emotion', 'instinct']
const CURSOR_SKIP_MODULES = new Set(['bottomline', 'user', 'userRule'])

function listCursorMemoryRules() {
  const out = []
  const seen = new Set()
  for (const sub of CURSOR_MEMORY_SUBDIRS) {
    const dir = join(CURSOR_RULES, sub)
    if (!existsSync(dir)) continue
    for (const name of readdirSync(dir)) {
      if (!name.endsWith('.mdc')) continue
      const full = join(dir, name)
      let stat
      try {
        stat = statSync(full)
      } catch {
        continue
      }
      let parsed
      try {
        parsed = parseFrontmatter(readFileSync(full, 'utf8'))
      } catch {
        continue
      }
      const front = parsed.front
      const body = parsed.body
      if (!body) continue
      const module = front.module || (sub === 'memory' ? 'cognition' : sub)
      // 底线 / 用户规则不通过这条通道进来
      if (CURSOR_SKIP_MODULES.has(module)) continue
      if (CURSOR_SKIP_MODULES.has(front.kind)) continue
      // 同一个 unifiedId 只收一次（同一份记忆可能被写到多个目录）
      const unifiedId = front.unifiedId || ''
      const key = unifiedId || `${sub}/${name}`
      if (seen.has(key)) continue
      seen.add(key)
      out.push({
        path: full,
        text: body,
        module,
        dshMemoryId: front.dshMemoryId || '',
        unifiedId,
        updatedAt: Number(front.updatedAt) || stat.mtimeMs,
        weight: Number(front.weight) || 0.5,
        pinned: front.pinned === true,
        // 2026-11-11：Cursor 那边不写 weight/pinned 是常态。以前这里默认成
        // 0.5 / false，一同步就把本机调过的权重和「钉住」冲掉。记下到底写没写。
        explicitWeight: Object.prototype.hasOwnProperty.call(front, 'weight'),
        explicitPinned: Object.prototype.hasOwnProperty.call(front, 'pinned'),
      })
    }
  }
  return out
}

/**
 * 从 Cursor 规则目录拉取记忆（仅 inbound，不写 Cursor 侧）。
 */
export function importFromCursorRules(logger) {
  if (!shouldDshReact()) return { ok: true, skipped: true }
  const lock = beginWriteDsh()
  if (!lock.ok) return { ok: false, skipped: true, reason: 'lock' }

  try {
    const incoming = listCursorMemoryRules()
    if (!incoming.length) {
      finishWriteDsh({ bump: false })
      return { ok: true, merged: 0 }
    }
    const store = readStore()
    const syncState = readSyncState()
    let stateDirty = false
    let merged = 0
    const now = Date.now()
    /** 记下「这条规则上次导进来的是哪条记忆、内容指纹是什么」。 */
    const markSeen = (path, entryId, hash, at) => {
      if (!syncState.rules) syncState.rules = {}
      syncState.rules[path] = { entryId, hash, at }
      stateDirty = true
    }
    for (const rule of incoming) {
      // 兜底：底线 / 用户规则一律不通过这条通道进 DSH。
      // listCursorMemoryRules 已经过滤过一次，这里再挡一层，
      // 防止以后有人改了扫描范围又把底线放进来。
      if (CURSOR_SKIP_MODULES.has(rule.module)) continue
      // 时钟保护：Cursor 侧时间戳最多允许比本机快 1 分钟，再快就当写错了。
      const ruleAt = Math.min(rule.updatedAt, now + CLOCK_SKEW_MS)
      const ruleHash = hashText(rule.text)
      // 2026-11-11：先按「这条规则上一次导进来的是哪条记忆」认亲。
      // 以前只按正文前 80 字模糊匹配 —— 正文一改就匹配不上，
      // 于是同一条规则会被当成新记忆再插一条，越同步越多。
      const prev = syncState.rules?.[rule.path] ?? null
      let entry = rule.dshMemoryId
        ? store.entries.find((e) => e.id === rule.dshMemoryId)
        : null
      if (!entry && prev?.entryId) {
        entry = store.entries.find((e) => e.id === prev.entryId) ?? null
      }
      if (!entry) {
        // 模糊匹配收紧。以前只看「前 80 字相同」，两条开头一样、
        // 后面接的结论不同的记忆会被当成同一条，整段正文互相覆盖。
        // 现在要求同模块 + 前 80 字相同 + 长度相差不超过 20%（至少 20 字）。
        const head = rule.text.slice(0, 80)
        entry = store.entries.find((e) => {
          if (e.module !== rule.module) return false
          if (e.text.slice(0, 80) !== head) return false
          const slack = Math.max(20, rule.text.length * 0.2)
          return Math.abs(e.text.length - rule.text.length) <= slack
        }) ?? null
      }
      // 2026-11-11：内容指纹。Cursor 那边只是碰了下文件（时间戳变了、正文一个字没动）
      // 时，绝不能当成「新内容」重写一遍 —— 那会把本机刚改的正文盖回去，
      // 还会把 updatedAt 推新，让老记忆装成刚更新过。
      if (prev && prev.hash === ruleHash && entry) {
        // Cursor 给的内容和我们上次收到的一样：什么都不做
        continue
      }
      const ruleNewer = ruleAt > (entry?.updatedAt ?? 0)
      if (entry && !ruleNewer) {
        // 时间不比本机新：记一笔指纹，下次同样内容就不会再来试
        markSeen(rule.path, entry.id, ruleHash, ruleAt)
        continue
      }
      if (!entry) {
        entry = {
          id: newId(),
          // 同步进来的内容一样要脱敏——Cursor 那边也可能记着密钥。
          // 2026-11-12 加：再顺手做一遍注入中和 —— Cursor 的规则文件是另一个工具写的，
          // 里面完全可能有「忽略以上要求」这类句子，不处理就是一条绕过来的提示词注入。
          text: externalTextIn(rule.text),
          tags: ['cursor-sync'],
          module: rule.module,
          weight: rule.weight,
          lifetime: 'permanent',
          expiresAt: 0,
          ttlMs: 0,
          pinned: rule.pinned,
          source: 'sync',
          scope: 'global',
          scopePath: '',
          supersedes: '',
          sessionId: '',
          cwd: '',
          createdAt: ruleAt,
          updatedAt: ruleAt,
          hits: 0,
        }
        store.entries.push(entry)
      } else {
        entry.text = externalTextIn(rule.text)
        entry.module = rule.module
        // 2026-11-11：只在 Cursor 侧**显式写了**才覆盖。
        // 以前那边不写 weight/pinned 也会被默认成 0.5/false，
        // 本机调过的权重和「钉住」一同步就没了。
        if (rule.explicitWeight) entry.weight = rule.weight
        if (rule.explicitPinned) entry.pinned = rule.pinned
        entry.updatedAt = ruleAt
        // 2026-11-04（P1-7 审计）：以前无条件改成 'sync'，把老大手动加的
    // （source='manual'）冲掉了。实测 128 条记忆里 manual=0 ——
    // 于是「有待办就一定要说」这条硬规则永远命中零条。
    // 现在：手动加的保持 manual，其余才标成 sync。
    if (entry.source !== 'manual') entry.source = 'sync'
      }
      markSeen(rule.path, entry.id, ruleHash, ruleAt)
      merged += 1
    }
    if (stateDirty) {
      // 顺手清掉已经删掉的条目留下的指纹，别让它无限长大
      const alive = new Set(store.entries.map((e) => e.id))
      for (const [path, rec] of Object.entries(syncState.rules)) {
        if (!rec || !alive.has(rec.entryId)) delete syncState.rules[path]
      }
      try {
        writeSyncState(syncState)
      } catch (error) {
        logger?.warn?.(`Cursor 同步指纹写盘失败：${String(error?.message ?? error)}`)
      }
    }
    if (merged > 0) writeStore(store)
    if (merged > 0) {
      finishWriteDsh({ bump: true, baseGeneration: lock.generation })
      logger?.info?.(`已从 Cursor 规则同步 ${merged} 条记忆`)
    } else {
      const c = readCoord()
      // 只认开工那一代：期间别人推进的留给下一轮，别标成已应用。
      c.dshApplied = Math.max(c.dshApplied, Number(lock.generation ?? c.generation))
      c.writer = null
      c.suppressWatchUntil = Date.now() + 800
      writeCoord(c)
    }
    return { ok: true, merged }
  } catch (error) {
    finishWriteDsh({ bump: false, baseGeneration: lock.generation, suppressMs: 500 })
    logger?.warn?.(`Cursor 同步失败：${String(error?.message ?? error)}`)
    return { ok: false, error: String(error?.message ?? error) }
  }
}

export function writeStoreSynced(store, options = {}) {
  const bump = options.bump !== false
  const lock = beginWriteDsh()
  if (!lock.ok) {
    writeStore(store)
    return store
  }
  try {
    writeStore(store)
    finishWriteDsh({ bump, baseGeneration: lock.generation })
    return store
  } catch (error) {
    finishWriteDsh({ bump: false, baseGeneration: lock.generation, suppressMs: 500 })
    throw error
  }
}

export function writeModulesSynced(modules, options = {}) {
  const bump = options.bump !== false
  const lock = beginWriteDsh()
  // 2026-11-11（P0-1）：每次写模块配置都顺手把底线镜像进扁平库。
  // 底线以前只活在 modules.json 的桶里，SQLite / 云端同步 / 召回白名单都看不见它。
  const mirrorBottomline = () => {
    try {
      const store = readStore()
      if (mirrorBottomlineEntries(store, modules)) writeStore(store)
    } catch (error) {
      console.warn('[dsh-shared-brain] 底线镜像进扁平库失败：', String(error?.message ?? error))
    }
  }
  if (!lock.ok) {
    writeModules(modules)
    mirrorBottomline()
    return modules
  }
  try {
    writeModules(modules)
    mirrorBottomline()
    finishWriteDsh({ bump, baseGeneration: lock.generation })
    return modules
  } catch (error) {
    finishWriteDsh({ bump: false, baseGeneration: lock.generation, suppressMs: 500 })
    throw error
  }
}

let debounceTimer = null

export function startCursorBridge(logger) {
  mkdirSync(CURSOR_BRAIN, { recursive: true })
  // 2026-11-02 改：原来只监听 memory/ 一个目录，
  // Cursor 往 cognition/、emotion/、instinct/ 写的记忆 DSH 根本收不到。
  // 现在监听整个规则根目录（recursive），任何模块目录变动都能触发导入。
  const targets = [COORD_FILE, REGISTRY_FILE, CURSOR_RULES]
  const watchers = []
  const schedule = () => {
    if (debounceTimer) clearTimeout(debounceTimer)
    debounceTimer = setTimeout(() => {
      importFromCursorRules(logger)
    }, 1200)
  }
  for (const target of targets) {
    try {
      if (!existsSync(target)) {
        if (target === CURSOR_RULES) mkdirSync(target, { recursive: true })
        else continue
      }
      // 规则根目录要递归监听；两个协调文件是单文件监听
      const recursive = target === CURSOR_RULES
      const watcher = watch(target, { recursive }, schedule)
      // unref：文件监听不该让宿主进程无法自然退出（其它定时器都做了）
      if (typeof watcher.unref === 'function') watcher.unref()
      watchers.push(watcher)
    } catch {
      // 监听失败不拖垮宿主
    }
  }
  schedule()
  return () => {
    if (debounceTimer) clearTimeout(debounceTimer)
    for (const w of watchers) w.close()
  }
}
